package com.aditya.fefo.controller; import com.aditya.fefo.dto.BatchDtos.*; import com.aditya.fefo.infrastructure.CurrentUser; import com.aditya.fefo.service.BatchService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/batches") public class BatchController {private final BatchService s;public BatchController(BatchService s){this.s=s;}@GetMapping public List<BatchResponse> list(@RequestParam(required=false) UUID productId){return s.list(productId);}@GetMapping("/{id}") public BatchResponse get(@PathVariable UUID id){return s.get(id);}@PostMapping @PreAuthorize("hasRole('ADMIN')") public BatchResponse create(@Valid @RequestBody CreateBatchRequest r){return s.create(r,CurrentUser.id());}}
